const inbound = $('2. Fetch Daily Inbound Volume Postgres').first().json;
const ticketStats = $input.first().json;

const totalEmailsToday = Number(inbound.total_emails_today) || 0;
const spamBlockedToday = Number(inbound.spam_blocked_today) || 0;

const totalTickets = Number(ticketStats.total_tickets) || 0;
const resolvedTickets = Number(ticketStats.resolved_tickets) || 0;
const p1CountToday = Number(ticketStats.p1_count) || 0;
const pendingTickets = Number(ticketStats.pending_tickets) || 0;
const slaComplianceRate = Number(ticketStats.sla_compliance_rate) || 100.0;

// Tính toán trung bình P1 trong 7 ngày qua (baseline)
const p1Past7Days = Number(ticketStats.p1_past_7_days) || 0;
const baselineDailyP1 = Math.max(1.0, p1Past7Days / 7);

// Tính tỷ lệ tăng trưởng P1 so với mức trung bình
const increasePercent = Math.round(((p1CountToday - baselineDailyP1) / baselineDailyP1) * 100);

// Đánh cờ is_spike_detected = true nếu phát sinh lỗi P1 vượt quá 20%
const isSpikeDetected = (p1CountToday > 0 && increasePercent > 20);

const summaryDate = new Date().toISOString().slice(0, 10);

return [{
  json: {
    summary_date: summaryDate,
    total_emails_today: totalEmailsToday,
    spam_blocked_today: spamBlockedToday,
    total_tickets: totalTickets,
    resolved_tickets: resolvedTickets,
    pending_tickets: pendingTickets,
    p1_count: p1CountToday,
    baseline_daily_p1: Number(baselineDailyP1.toFixed(2)),
    increase_percent: increasePercent,
    is_spike_detected: isSpikeDetected,
    sla_compliance_rate: slaComplianceRate
  }
}];

const metrics = $('4. Detect Incident Spike Code').first().json;
const aiResp = $input.first().json;

let aiData = {};
let rawText = '';
if (aiResp && aiResp.output) {
  rawText = String(aiResp.output);
} else if (aiResp && aiResp.candidates && aiResp.candidates[0]?.content?.parts?.[0]?.text) {
  rawText = aiResp.candidates[0].content.parts[0].text;
}

if (rawText) {
  try {
    const clean = rawText.replace(/\`\`\`json/g, '').replace(/\`\`\`/g, '').trim();
    aiData = JSON.parse(clean);
  } catch(e) {}
}

const summaryText = aiData.executive_summary || (metrics.is_spike_detected 
  ? `Hệ thống ghi nhận sự gia tăng đột biến lỗi mức độ P1 (${metrics.p1_count} sự cố, tăng ${metrics.increase_percent}%). Yêu cầu đội ngũ trực nhật kiểm tra ngay lập tức.`
  : `Hệ thống vận hành ổn định trong ngày ${metrics.summary_date}. Tổng số ${metrics.total_emails_today} email đã tiếp nhận, tỷ lệ tuân thủ SLA đạt ${metrics.sla_compliance_rate}%.`);

const htmlReport = `<!DOCTYPE html><html><body><h2>Báo cáo điều hành ngày ${metrics.summary_date}</h2><p>${summaryText}</p></body></html>`;

return [{
  json: {
    ...metrics,
    executive_summary: summaryText,
    html_digest: htmlReport
  }
}];

